function moneyShort(n:number){if(n<=0)return "₹0";return n>=100000?`₹${(n/100000).toFixed(n>=1000000?0:1)}L`:`₹${Math.round(n/1000)}k`}
function calendarDates(month:string):(string|null)[]{const [year,monthNumber]=month.split("-").map(Number);const first=new Date(year,monthNumber-1,1).getDay();const count=new Date(year,monthNumber,0).getDate();const days:(string|null)[]=[...Array(first).fill(null),...Array.from({length:count},(_,i)=>`${month}-${String(i+1).padStart(2,"0")}`)];return [...days,...Array((7-days.length%7)%7).fill(null)]}
function shiftMonth(month:string,amount:number){const [year,monthNumber]=month.split("-").map(Number);const d=new Date(year,monthNumber-1+amount,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`}
async function shrinkPhoto(file:File){if(!file.type.startsWith("image/"))throw new Error("Choose an image file.");if(file.size>8*1024*1024)throw new Error("Choose a photo smaller than 8 MB.");const bitmap=await createImageBitmap(file);const side=144;const canvas=document.createElement("canvas");canvas.width=side;canvas.height=side;const ctx=canvas.getContext("2d");if(!ctx)throw new Error("This browser could not prepare the photo.");const crop=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-crop)/2,(bitmap.height-crop)/2,crop,crop,0,0,side,side);bitmap.close();let quality=.62;let out=canvas.toDataURL("image/jpeg",quality);while(out.length>18000&&quality>.3){quality-=.08;out=canvas.toDataURL("image/jpeg",quality)}if(out.length>22000)throw new Error("Photo is too detailed to store safely. Choose a smaller image.");return out}
async function shrinkLogo(file:File){if(!file.type.startsWith("image/"))throw new Error("Choose an image file.");if(file.size>8*1024*1024)throw new Error("Choose a logo smaller than 8 MB.");const bitmap=await createImageBitmap(file);const scale=Math.min(1,640/bitmap.width,260/bitmap.height);const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext("2d");if(!ctx)throw new Error("This browser could not prepare the logo.");ctx.fillStyle="#ffffff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let quality=.82;let out=canvas.toDataURL("image/jpeg",quality);while(out.length>26000&&quality>.35){quality-=.07;out=canvas.toDataURL("image/jpeg",quality)}if(out.length>30000)throw new Error("Logo is too detailed to save safely. Choose a smaller image.");return out}
