  function updateWorkerProfile(f:FormData){const worker=data.workers.find(w=>w.id===selectedWorker);if(!worker)return;const name=String(f.get("name")||"").trim(),phone=String(f.get("phone")||"").trim(),role=f.get("role") as "Labour"|"Mistri";if(!name||!(role==="Labour"||role==="Mistri")){setNotice("Enter a valid name and work role.");return}const photoFile=f.get("photo");const apply=async()=>{try{const photo=photoFile instanceof File&&photoFile.size?await shrinkPhoto(photoFile):worker.photo;save({...data,workers:data.workers.map(w=>w.id===worker.id?{...w,name,phone,role,photo}:w)});setModal("worker-profile");}catch(e){setNotice(e instanceof Error?e.message:"Worker profile could not be saved.")}};void apply()}
  async function permanentlyDeleteWorker(){if(deleteBusy)return;const worker=dataRef.current.workers.find(w=>w.id===selectedWorker);if(!worker)return;const blockers=workerDeletionBlockers(dataRef.current,worker.id);if(!canConfirmWorkerDeletion(auth,deleteText,blockers)){setNotice(blockers.length?"Deletion blocked; the linked records will be retained.":"Type DELETE to confirm as the Owner.");return}if(!supabase||!revisionRef.current){setNotice("The shared workspace is not ready. Worker was not deleted.");return}setDeleteBusy(true);setSyncing(true);try{const {data:result,error}=await supabase.rpc("delete_worker_from_workspace",{p_worker_id:worker.id,expected_revision:revisionRef.current,confirmation_text:deleteText});if(error)throw error;const value=result as {status:string;revision?:string;snapshot?:AppData;reasons?:string[]};if(value.status==="blocked"){setNotice("Worker was not deleted. Retained records: "+(value.reasons||[]).join(", ")+".");return}if(value.status==="conflict"&&value.revision&&value.snapshot){const cloud=validateBackup(value.snapshot);const local=dataRef.current;localStorage.setItem(LOCAL_RECOVERY_KEY,JSON.stringify(local));setRecoveryAvailable(true);setCloudConflict({snapshot:cloud,revision:value.revision,localSnapshot:local});dataRef.current=cloud;setData(cloud);revisionRef.current=value.revision;lastSyncedRef.current=JSON.stringify(cloud);setPendingWrite(true);setNotice("The shared workspace changed on another device. Review the conflict before deleting.");return}if(value.status==="not_found"){setNotice("This worker is no longer in the shared workspace. No deletion was recorded.");return}if(value.status!=="deleted"||!value.revision||!value.snapshot)throw new Error("Cloud did not confirm the worker deletion.");const cloud=validateBackup(value.snapshot);dataRef.current=cloud;setData(cloud);revisionRef.current=value.revision;lastSyncedRef.current=JSON.stringify(cloud);setCloudReady(true);setPendingWrite(false);setSyncError("");clearPendingWorkspace();setDeleteText("");setModal(null)}catch(e){setNotice(e instanceof Error?"Worker deletion failed: "+e.message:"Worker deletion failed.")}finally{setDeleteBusy(false);setSyncing(false)}}
  async function signIn(f:FormData){if(!supabase)return;setAuthError("");const {error}=await supabase.auth.signInWithPassword({email:String(f.get("email")),password:String(f.get("password"))});if(error)setAuthError(error.message)}
 async function sendPasswordReset(){if(!supabase||!authEmail){setAuthError("Enter the owner email first.");return}setAuthError("");const {error}=await supabase.auth.resetPasswordForEmail(authEmail,{redirectTo:window.location.origin});setResetMessage(error?"Could not send the recovery email. Check the account and email settings.":"If this email has an account, a password recovery link has been sent.")}
