 async function enableWageReminders(){if(typeof Notification==="undefined"){setNotice("This browser does not support notifications.");return}const permission=await Notification.requestPermission();if(permission!=="granted"){setNotice("Allow notifications in browser settings to receive wage reminders.");return}localStorage.setItem("lf-wage-reminders-enabled","true");setRemindersEnabled(true);save({...data,monthlyWageReminderDay:data.monthlyWageReminderDay||1});setNotice("Daily monthly-wage reminders enabled on this device.")}
