  <div className="quick-panel"><div><span className="quick-icon"><Activity size={19}/></span><div><b>{t.quickActions}</b><small>Common tasks, one tap away</small></div></div><button onClick={()=>{const w=data.workers.find(x=>x.status==="Active");if(w){setSelectedWorker(w.id);setSection("workers");setModal("worker-profile")}else setNotice("Add a worker profile first.")}}><CalendarDays size={17}/>{t.markAttendance}</button><button onClick={()=>setModal("worker")}><Users size={17}/>{t.addWorker}</button><button onClick={()=>{setLedgerKind("Project expense");setModal("ledger")}}><ArrowUpRight size={17}/>{t.recordExpense}</button><button onClick={()=>setModal("contract")}><Building2 size={17}/>{t.newContract}</button></div>
